      if (sides[side] + sorted[index] > target) continue;
      sides[side] += sorted[index];
      if (backtrack(index + 1)) return true;
      sides[side] -= sorted[index];
      if (sides[side] === 0) break;
    }
    return false;
  }
  return backtrack(0);
}
