    for (let sum = -total; sum <= total; sum++) {
      if (dp[sum + offset] !== 0) { next[sum + value + offset] += dp[sum + offset]; next[sum - value + offset] += dp[sum + offset]; }
    }
    for (let i = 0; i < dp.length; i++) dp[i] = next[i];
  }
  return dp[target + offset];
